1	/* =====================================================================
2	   Đà Nẵng 3D — điểm vào: khởi tạo theo thứ tự, rồi chạy vòng animate.
3	   Thứ tự dựng cảnh giữ nguyên như bản một file: chuỗi ngẫu nhiên có hạt giống (common/math.ts → rand)
4	   được dùng lần lượt, đổi thứ tự sẽ đổi vị trí nhà, cây, xe.
5	   ===================================================================== */
6	import * as THREE from 'three';
7	import { initI18n } from './i18n';
8	import { renderer, scene, camera, controls } from './core/renderer';
9	import { shared, windFx } from './core/shared';
10	import { buildLights, stepLights, lightState } from './core/lights';
11	import { buildSky, shadowCenter } from './core/sky';
12	import { buildWater, water, reflectState } from './core/water';
13	import { applyNight, stepNight, dayNight } from './core/dayNight';
14	import { renderFrame, onResize, scheduleResize } from './core/postprocessing';
15	import { perf } from './core/perf';
16	import { prewarm, warmLightSets } from './core/prewarm';
17	import { quality } from './core/quality';
18	import { buildRiverBanks } from './environment/river';
19	import { buildMountains } from './environment/mountains';
20	import { buildStreets, finalizeRoads } from './environment/streets';
21	import { drClearRoads } from './environment/driveRoads';
22	import { buildCity } from './environment/city';
23	import { buildTrees, buildStreetLamps, treesTest } from './environment/trees';
24	import { buildTraffic, buildBoats, updateTraffic, updateBoats, boatsTest, trafficTest } from './environment/traffic';
25	import {
26	  buildBridgeDeck, buildPiers, buildDragonBody, buildScales, buildHangers, buildDragonHead,
27	  createFire, createWaterJet, updateShow, updateEffects, show, showLabel, mouthW
28	} from './bridges/dragon';
29	import { ThuanPhuocBridge } from './bridges/thuan-phuoc';
30	import { TranThiLyBridge } from './bridges/tran-thi-ly';
31	import { SongHanBridge } from './bridges/song-han';
32	import { HanTunnel } from './bridges/han-tunnel';
33	import { SunWheel, swRide } from './bridges/sun-wheel';
34	import { buildRiverfront, updateRiverfront } from './environment/riverfront';
35	import { buildDragonPeople, updateDragonPeople, peopleTest } from './environment/pedestrians';
36	import { crowdLoad, crowdGet } from './common/people/crowdData';
37	import { crowdUsable } from './common/people/crowd';
38	import { stBlocky } from './explore/stroll/blocky';
39	import { buildWeather, updateWeather } from './environment/weather';
40	import { updateCamera, hrDrive } from './views/camera';
41	import { cam, keys } from './views/state';
42	import { TOURS, tour } from './views/tour';
43	import { exCreate, exStep, exInputFromKeys } from './explore/flight';
44	import { exBuildGlider, exPlaceGlider } from './explore/glider';
45	import { exChase } from './explore/chase';
46	import { explore, setupExplore } from './explore';
47	import { stroll } from './explore/stroll';
48	import { drive } from './explore/drive';
49	import { bike } from './explore/bike';
50	import { stValid, stGroundY, stMove } from './explore/stroll/map';
51	import { stCamPlace } from './explore/stroll/camera';
52	import { stAvatars } from './explore/stroll/avatars';
53	import { exMulti } from './explore/multi';
54	import { exRemotes } from './explore/multi/remote';
55	import { exChat } from './explore/multi/chat';
56	import { exDrivers } from './explore/multi/remoteDrive';
57	import { CONFIG } from './config';
58	import { audio } from './audio';
59	import { narration } from './audio/narration';
60	import { setupUI } from './ui/setupUI';
61	import { setupQualityUI } from './ui/qualityUI';
62	import { setupCompactUI, ui as compactState, openSheet, closeSheets, reveal } from './ui/compactUI';
63	import { setupEnvUI, type EnvUI } from './ui/envUI';
64	import { bindLiveMode } from './ui/liveUI';
65	import { createLiveEnv, liveNextDelay, type LiveEnv, type EnvMode } from './realtime/liveEnv';
66	import { updateHrUI } from './ui/hrUI';
67	
68	initI18n();
69	void narration.init();
70	window.addEventListener('resize', scheduleResize); window.addEventListener('orientationchange', scheduleResize);
71	
72	/* ============================ Khởi tạo ============================ */
73	// đám đông người thật (D-032): chờ tải xong (tối đa CONFIG.people.crowd.loadTimeoutMs; lỗi → null, hình khối) để mọi lưới / vật liệu có trước prewarm; không đổi thứ tự dựng.
74	// Renderer đã tạo lúc import core/renderer: thiếu WEBGL_multi_draw thì không tải, không chờ (r165 sẽ vẽ mỗi người một lệnh ⇒ hình khối)
75	if (renderer.extensions.has('WEBGL_multi_draw')) await crowdLoad();
76	else console.info('[people] trình duyệt không có WEBGL_multi_draw: không tải đám đông người thật, dùng hình khối');
77	buildLights();
78	buildSky();
79	buildWater();
80	buildRiverBanks();
81	buildMountains();
82	buildBridgeDeck();
83	buildPiers();
84	buildDragonBody();
85	buildScales();
86	buildHangers();
87	buildDragonHead();
88	buildStreets();
89	finalizeRoads();
90	buildCity();
91	buildTrees();
92	buildStreetLamps();
93	buildTraffic();
94	buildBoats();
95	const thuanPhuoc = new ThuanPhuocBridge();
96	scene.add(thuanPhuoc.group);
97	const tranThiLy = new TranThiLyBridge();
98	scene.add(tranThiLy.group);
99	const songHan = new SongHanBridge();
100	scene.add(songHan.group);
101	const hanTunnel = new HanTunnel();     // sau mọi lệnh dựng có dùng rand(): chỉ dọn nhà, cây trên tuyến bằng cách thu nhỏ instance
102	scene.add(hanTunnel.group);
103	const riverfront = buildRiverfront();    // sau HanTunnel: dọn nhà bị đè bằng scale 0, không đụng chuỗi rand()
104	drClearRoads(thuanPhuoc.houses);         // sau buildRiverfront: dọn nhà / cây / đèn trên đường mới của chế độ lái (D-034) bằng scale 0, không đụng chuỗi rand()
105	const sunWheel = new SunWheel();         // sau buildRiverfront, trước buildWeather: dọn nền bằng scale 0, không đụng chuỗi rand()
106	scene.add(sunWheel.group);
107	buildDragonPeople();                     // sau mọi lệnh dùng rand(), trước buildWeather: người Cầu Rồng dùng rng riêng
108	const weather = buildWeather();          // sau buildRiverfront (sau mọi rand()): chụp giá trị gốc khí quyển/đường, dựng mưa (ẩn), điều biến sau applyNight
109	weather.attachSwing(songHan.ctrl);       // bão: Cầu sông Hàn không quay (SwingController.canStart)
110	const bridges = [thuanPhuoc, tranThiLy, songHan, hanTunnel, sunWheel];
111	const bridgeKeys = ['tp', 'ttl', 'sh', 'hr', 'sw'];   // tên bước khi đo hiệu năng (constructor.name bị đổi khi build)
112	createFire();
113	createWaterJet();
114	const ui = setupUI({ thuanPhuoc, tranThiLy, songHan, hanTunnel, sunWheel });
115	onResize();
116	applyNight(0, 0);
117	quality.init(() => cam.mode === 'fly');   // bậc chất lượng ban đầu (theo thiết bị / lựa chọn đã lưu); không đổi bậc giữa chuyến bay camera
118	setupQualityUI();
119	setupCompactUI();
120	/* ?test&perf: bật đo thời gian CPU từng bước trong vòng animate (tests/perf-check.mjs) */
121	const query = new URLSearchParams(location.search);
122	// Giờ + thời tiết thực tế (D-042); ?test không gọi Open-Meteo trừ khi có env=live. Chỉ là phần thông tin: lỗi ở đây không được chặn khám phá / vòng vẽ bên dưới
123	let envUi: EnvUI | undefined;
124	// nhiễu nhịp làm mới (D-043): Math.random để mỗi máy gọi Open-Meteo một giây khác (không phải ngẫu nhiên của cảnh, không đụng rand())
125	try { envUi = setupEnvUI({ live: !query.has('test') || query.get('env') === 'live', nextDelay: (now) => liveNextDelay(now, CONFIG.live, Math.random), skew: { maxMs: CONFIG.live.skewMaxMs, stepMs: CONFIG.live.obsStepMs } }); }
126	catch (e) { console.warn('env: không dựng được chỉ báo giờ / thời tiết', e); const envEl = document.getElementById('env'); if (envEl) envEl.style.display = 'none'; }
127	// Môi trường theo thời tiết + giờ thật (D-043): Trực tiếp mặc định, ?test mặc định Mô phỏng (test cũ tất định), ?envmode=live|manual ép.
128	// Dùng chính kho của envUi (không tạo kho thứ hai; ?test không gọi mạng trừ khi env=live). envUi hỏng ⇒ không có bộ điều khiển, cảnh chạy Mô phỏng như cũ
129	const envModeQ = query.get('envmode');
130	const envMode: EnvMode = envModeQ === 'live' || envModeQ === 'manual' ? envModeQ : query.has('test') ? 'manual' : 'live';
131	let liveEnv: LiveEnv | null = null;
132	if (envUi) {
133	  try { liveEnv = createLiveEnv({ cfg: CONFIG.live, lat: CONFIG.env.lat, lon: CONFIG.env.lon, refreshMs: CONFIG.env.refreshMs, now: envUi.now, store: envUi.store, weather, dayNight, initial: envMode }); }
134	  catch (e) { console.warn('live: không dựng được chế độ Trực tiếp, dùng Mô phỏng', e); liveEnv = null; }
135	  // Giao diện hai chế độ (D-043 Task 6): chỉ khi có bộ điều khiển; liveEnv null ⇒ không công tắc, không khóa, như trước D-043
136	  if (liveEnv) { const le = liveEnv, eu = envUi; try { bindLiveMode(le, { store: eu.store, syncSim: ui.syncSim, renderEnv: eu.render }); } catch (e) { console.warn('live: không gắn được giao diện chế độ', e); } }
137	}
138	setupExplore(songHan.ctrl);
139	
140	/* Móc kiểm thử: chỉ bật khi URL có ?test (dùng cho tests/*.mjs đo draw call và chạy Tour) */
141	/* Chỉ các lớp three mà tests/*.mjs dùng: đưa cả namespace THREE vào một object làm Rollup giữ lại mọi export của three (D-018) */
142	const TEST_THREE = { Vector3: THREE.Vector3, Quaternion: THREE.Quaternion, Matrix4: THREE.Matrix4, Euler: THREE.Euler, Box3: THREE.Box3, Raycaster: THREE.Raycaster };
143	/* Cho test nhiều người (Task 5; sảnh thật là Task 6): mở phiên, vào phòng bằng tên, bay khi được cấp slot */
144	const multiTest = {
145	  url: () => exMulti.url(), get session() { return exMulti.session; }, remotes: exRemotes, drivers: exDrivers, chat: exChat,   // drivers: xe người khác (bike-multi: debug(slot) xe máy thật + nhân vật)
146	  fly(name: string): boolean {
147	    return exMulti.begin(() => {
148	      exMulti.onChange = () => { if (exMulti.session!.phase === 'flying' && !explore.active()) explore.start(); };
149	      exMulti.session!.join(name);
150	    });
151	  }
152	};
153	if (query.has('test')) {
154	  perf.on = query.has('perf');
155	  (window as unknown as { __app: unknown }).__app = { reflectState, renderer, scene, camera, controls, cam, shared, songHan, hr: hanTunnel, sunWheel, riverfront, weather, hrDrive, swRide, windFx, THREE: TEST_THREE, dayNight, lights: lightState, tours: TOURS, tour, narration, audio, perf, quality, ui: { ...ui, ui: compactState, openSheet, closeSheets, reveal }, explore, keys, multi: multiTest, exFlight: { exCreate, exStep, exInputFromKeys, exBuildGlider, exPlaceGlider, exChase, CONFIG_explore: CONFIG.explore }, boats: boatsTest, traffic: trafficTest, trees: treesTest, people: peopleTest,
156	    stroll: { stroll, stValid, stGroundY, stMove, stCamPlace, CONFIG_stroll: CONFIG.stroll, avatars: stAvatars }, drive, bike, env: envUi, live: liveEnv };
157	}
158	
159	/* ============================ Vòng lặp ============================ */
160	const clock = new THREE.Clock();
161	const fpsEl = document.getElementById('fps'), callsEl = document.getElementById('calls'), showEl = document.getElementById('showState'), ftimeEl = document.getElementById('ftime');
162	let frames = 0, fpsT = 0, fpsLast = performance.now(), firstFrame = true;
163	function animate() {
164	  requestAnimationFrame(animate);
165	  const now0 = performance.now();
166	  perf.tick(now0);
167	  const dt = Math.min(clock.getDelta(), 0.05), time = clock.elapsedTime;
168	  let pt = perf.start();
169	  shared.uTime.value = time;
170	  shadowCenter.set(Math.round(controls.target.x / 8) * 8, 0, Math.round(controls.target.z / 8) * 8);
171	  if (liveEnv) liveEnv.update(dt);                          // Trực tiếp (D-043): dayNight.target + mặt trời thật, trước stepNight; Mô phỏng: không làm gì
172	  stepNight(dt);
173	  applyNight(dayNight.night, time, liveEnv ? liveEnv.sun : null); pt = perf.lap('night', pt);   // sun null (Mô phỏng / ?test) ⇒ như cũ
174	  updateWeather(dt, time, dayNight.night, camera);         // điều biến sau applyNight (D-009); camera: mưa quanh camera, tắt trong hầm
175	  water.material.uniforms.time.value += dt * 0.6 * windFx.waveSpeed;   // sóng trôi nhanh hơn theo gió (mặc định ×1)
176	  pt = perf.lap('weather', pt);
177	  updateShow(dt);
178	  updateEffects(dt, time); pt = perf.lap('effects', pt);
179	  updateTraffic(dt); updateDragonPeople(dt, time, camera); pt = perf.lap('traffic', pt);
180	  updateBoats(dt, time); pt = perf.lap('boats', pt);
181	  updateCamera(dt); explore.update(dt); stroll.update(dt); drive.update(dt); bike.update(dt); pt = perf.lap('camera', pt);
182	  for (let k = 0; k < bridges.length; k++) { bridges[k].update(dt, time, camera); pt = perf.lap(bridgeKeys[k], pt); }
183	  hanTunnel.holdBoats(songHan.boats.list);
184	  updateHrUI(camera);
185	  updateRiverfront(dt, time); pt = perf.lap('riverfront', pt);
186	  audio.setSwingDistance(camera.position.distanceTo(songHan.center));
187	  audio.update(dayNight.night, show.fireOn, show.waterOn, camera.position.distanceTo(mouthW)); pt = perf.lap('audio', pt);
188	  stepLights();                                             // bộ đèn ngày / đêm / đủ (D-031): sau mọi chỗ ghi cường độ đèn, trước khi vẽ
189	  quality.update(now0);                                     // bậc chất lượng (tự hạ khi lag), bóng đổ, giới hạn pixelRatio khi mưa
190	  const pw = perf.start(); warmLightSets(); perf.lap('lightWarm', pw);   // hâm nền bộ đèn day / night (D-031 'bg'): sau quality.update (biết khung này có vẽ lại bóng), trước lượt vẽ thật; xong thì trả về ngay
