1	import * as THREE from 'three';
2	import { camera, controls } from '../core/renderer';
3	import { clamp } from '../common/math';
4	import { CONFIG } from '../config';
5	import { t, stops, onChange } from '../i18n';
6	import { narration } from '../audio/narration';
7	import { TOUR_DEFS, type TourDef, type TourStop } from './tourStops';
8	import type { BridgeKey } from './presets';
9	import { cam } from './state';
10	
11	/* ============================ Tour tự động: đường bay + chú thích ============================ */
12	/* loop: false — đường bay mở (Tour 4 cầu): n − 1 đoạn bay + một đoạn "giữ" ở điểm cuối, hết thì trả điều khiển */
13	interface Tour extends TourDef {
14	  loop: boolean; posCurve: THREE.CatmullRomCurve3; tgtCurve: THREE.CatmullRomCurve3; base: number[]; durs: number[]; total: number;
15	}
16	export type TourKey = keyof typeof TOUR_DEFS;
17	export const TOURS = {} as Record<TourKey, Tour>;
18	for (const [k, T] of Object.entries(TOUR_DEFS) as [TourKey, TourDef][]) {
19	  const P = T.stops.map((s) => new THREE.Vector3(...s.pos)), Q = T.stops.map((s) => new THREE.Vector3(...s.target));
20	  const loop = T.loop !== false;
21	  const durs = P.map((p, i) => !loop && i === P.length - 1 ? CONFIG.tourAll.holdMin   // đoạn giữ ở điểm cuối
22	    : clamp(4 + p.distanceTo(P[(i + 1) % P.length]) / 45, 8, T.segMax ?? 16));           // đoạn dài bay lâu hơn để tốc độ đều
23	  TOURS[k] = {
24	    ...T, loop,
25	    posCurve: new THREE.CatmullRomCurve3(P, loop, 'centripetal'),
26	    tgtCurve: new THREE.CatmullRomCurve3(Q, loop, 'centripetal'),
27	    base: durs, durs: [...durs], total: durs.reduce((a, b) => a + b, 0)
28	  };
29	}
30	
31	/* Chú thích (và giọng đọc) chuyển sang điểm kế khi đi qua tỉ lệ này của đoạn bay */
32	const SWITCH = 0.55, PAD = 1.2;
33	
34	/* Có giọng thuyết trình thì kéo dài từng đoạn bay để đọc xong trước khi sang điểm dừng kế.
35	   Điểm dừng k hiện từ lúc 55% đoạn k-1 tới 55% đoạn k; chỉ đoạn k được kéo dài nên các điểm đã đủ chỗ vẫn đủ.
36	   Đường bay mở: điểm 0 hiện ngay từ đầu (không có đoạn trước); điểm cuối hiện tới hết đoạn giữ. */
37	function fitDurations(T: Tour) {
38	  const n = T.stops.length;
39	  T.durs.splice(0, n, ...T.base);
40	  for (let k = 0; k < n; k++) {
41	    const spoken = narration.duration(T.key, k), clip = Math.max(spoken ?? 0, T.stops[k].minSec ?? 0);   // minSec: giữ điểm này ít nhất chừng đó giây dù không có giọng
42	    if (spoken === null && !T.stops[k].minSec) continue;
43	    const prev = (k + n - 1) % n, before = !T.loop && k === 0 ? 0 : (1 - SWITCH) * T.durs[prev];
44	    T.durs[k] = Math.max(T.durs[k], (clip + PAD - before) / (!T.loop && k === n - 1 ? 1 : SWITCH));
45	  }
46	  T.total = T.durs.reduce((a, b) => a + b, 0);
47	}
48	function locate(T: Tour, t: number) {
49	  let i = 0, acc = 0;
50	  while (i < T.durs.length - 1 && acc + T.durs[i] < t) { acc += T.durs[i]; i++; }
51	  return { i, acc, f: (t - acc) / T.durs[i] };
52	}
53	for (const T of Object.values(TOURS)) fitDurations(T);
54	/* Tên nút góc nhìn → cầu có Tour đó */
55	export const TOUR_VIEWS: Record<string, TourKey> = Object.fromEntries(Object.entries(TOURS).map(([k, v]) => [v.view, k as TourKey]));
56	
57	export let activeTour: Tour = TOURS.dragon;
58	export const tour = { t: 0, shown: -1 };
59	let onTourSwingStop: (() => void) | null = null;   // Cầu sông Hàn gắn hàm quay cầu vào đây
60	export const setTourSwingHook = (fn: () => void) => { onTourSwingStop = fn; };
61	export const setActiveTour = (k: TourKey) => { activeTour = TOURS[k]; };
62	/* Móc cho công trình có hành vi riêng ở từng điểm dừng (Hầm sông Hàn: mặt cắt, mô phỏng dìm) và khi thoát Tour */
63	/* bridge: Tour 4 cầu tới cầu khác thì đổi bảng Thông số / danh sách góc nhìn (setupUI gắn selectBridge, tránh vòng import panel → camera → tour) */
64	/* sw: Tour Vòng quay Mặt Trời — gọi mỗi khi đổi điểm dừng (null = điểm thường) và khi thoát Tour (exit = true), sau khi cam.mode đã về 'orbit' */
65	export const tourHooks: { stop: ((s: TourStop) => void) | null; exit: (() => void) | null; bridge: ((k: BridgeKey) => void) | null; sw: ((phase: TourStop['sw'] | null, exit: boolean) => void) | null } = { stop: null, exit: null, bridge: null, sw: null };
66	
67	/* Giọng bật/tắt hoặc đổi ngôn ngữ: tính lại thời lượng (giữ nguyên vị trí trên đường bay) rồi đọc lại điểm dừng hiện tại */
68	function syncNarration() {
69	  const { i, f } = locate(activeTour, tour.t);
70	  for (const T of Object.values(TOURS)) fitDurations(T);
71	  tour.t = activeTour.durs.slice(0, i).reduce((a, b) => a + b, 0) + f * activeTour.durs[i];
72	  if (cam.mode === 'tour' && tour.shown >= 0) narration.play(activeTour.key, tour.shown); else narration.stop();
73	}
74	narration.onChange(syncNarration);
75	onChange(syncNarration);
76	
77	const els = {} as { box: HTMLElement; step: HTMLElement; title: HTMLElement; text: HTMLElement; bar: HTMLElement };
78	export const tourBox = () => els.box;
79	export function initTourCaption() {
80	  els.box = document.getElementById('tourCaption'); els.step = document.getElementById('tourStep');
81	  els.title = document.getElementById('tourTitle'); els.text = document.getElementById('tourText'); els.bar = document.getElementById('tourBar');
82	}
83	export function renderTourCaption(i: number) {
84	  const stop = stops(activeTour.key)[i];
85	  els.step.textContent = t('step', { i: i + 1, n: activeTour.stops.length });
86	  els.title.textContent = stop[0]; els.text.textContent = stop[1];
87	}
88	/* Đổi chữ NGAY trong khung hình rồi hiện dần (transition opacity của CSS). Bản gốc mờ đi rồi đổi chữ bằng setTimeout(300):
89	   khung hình nặng (bật mặt cắt hầm, biên dịch shader) làm timer trễ nên chú thích có lúc vẫn ghi điểm dừng trước */
90	export function showTourCaption(i: number) {
91	  const box = els.box;
92	  renderTourCaption(i);
93	  box.style.transition = 'none'; box.classList.add('fade'); void box.offsetWidth;   // ẩn tức thì (ép reflow để trình duyệt ghi nhận)
94	  box.style.transition = ''; box.classList.remove('fade');                          // rồi hiện dần
95	}
96	export function startTour() { cam.mode = 'tour'; controls.enabled = false; tour.t = 0; tour.shown = -1; }
97	export function exitTour() {
98	  if (cam.mode !== 'tour' && !(cam.mode === 'fly' && cam.flight.then === 'tour')) return;
99	  narration.stop(); tourHooks.exit?.();
100	  cam.flight.then = null; cam.mode = 'orbit'; controls.enabled = true;
101	  els.box.hidden = true; document.body.classList.remove('touring');
102	  document.querySelectorAll('[data-view]').forEach((b) => b.setAttribute('aria-pressed', 'false'));
103	  tourHooks.sw?.(null, true);
104	}
105	export function updateTour(dt: number) {
106	  const T = activeTour;
107	  const n = T.stops.length;
108	  tour.t = T.loop ? (tour.t + dt) % T.total : Math.min(tour.t + dt, T.total);
109	  const { i, f } = locate(T, tour.t);
110	  const e = 0.5 - 0.5 * Math.cos(Math.PI * f);       // chậm lại ở mỗi điểm dừng
111	  const u = T.loop ? (i + e) / n : Math.min((i + e) / (n - 1), 1);   // đường mở: đoạn giữ cuối đứng yên ở điểm cuối
112	  T.posCurve.getPoint(u, camera.position);
113	  camera.position.y = Math.max(camera.position.y, T.minY ?? 3);   // đường cong có thể võng xuống: giữ camera trên mặt nước (trừ Tour Hầm sông Hàn)
114	  T.tgtCurve.getPoint(u, controls.target);
115	  camera.lookAt(controls.target);
116	  const near = f < SWITCH || (!T.loop && i === n - 1) ? i : (i + 1) % n;
117	  if (near !== tour.shown) {
