31	/* Chú thích (và giọng đọc) chuyển sang điểm kế khi đi qua tỉ lệ này của đoạn bay */
32	const SWITCH = 0.55, PAD = 1.2;
33	
34	/* Có giọng thuyết trình thì kéo dài từng đoạn bay để đọc xong trước khi sang điểm dừng kế.
35	   Điểm dừng k hiện từ lúc 55% đoạn k-1 tới 55% đoạn k; chỉ đoạn k được kéo dài nên các điểm đã đủ chỗ vẫn đủ.
36	   Đường bay mở: điểm 0 hiện ngay từ đầu (không có đoạn trước); điểm cuối hiện tới hết đoạn giữ. */
37	function fitDurations(T: Tour) {
38	  const n = T.stops.length;
39	  T.durs.splice(0, n, ...T.base);
40	  for (let k = 0; k < n; k++) {
41	    const spoken = narration.duration(T.key, k), clip = Math.max(spoken ?? 0, T.stops[k].minSec ?? 0);   // minSec: giữ điểm này ít nhất chừng đó giây dù không có giọng
42	    if (spoken === null && !T.stops[k].minSec) continue;
43	    const prev = (k + n - 1) % n, before = !T.loop && k === 0 ? 0 : (1 - SWITCH) * T.durs[prev];
44	    T.durs[k] = Math.max(T.durs[k], (clip + PAD - before) / (!T.loop && k === n - 1 ? 1 : SWITCH));
45	  }
46	  T.total = T.durs.reduce((a, b) => a + b, 0);
47	}
48	function locate(T: Tour, t: number) {
49	  let i = 0, acc = 0;
50	  while (i < T.durs.length - 1 && acc + T.durs[i] < t) { acc += T.durs[i]; i++; }
51	  return { i, acc, f: (t - acc) / T.durs[i] };
52	}
53	for (const T of Object.values(TOURS)) fitDurations(T);
54	/* Tên nút góc nhìn → cầu có Tour đó */
55	export const TOUR_VIEWS: Record<string, TourKey> = Object.fromEntries(Object.entries(TOURS).map(([k, v]) => [v.view, k as TourKey]));
56	
57	export let activeTour: Tour = TOURS.dragon;
58	export const tour = { t: 0, shown: -1 };
59	let onTourSwingStop: (() => void) | null = null;   // Cầu sông Hàn gắn hàm quay cầu vào đây
60	export const setTourSwingHook = (fn: () => void) => { onTourSwingStop = fn; };
61	export const setActiveTour = (k: TourKey) => { activeTour = TOURS[k]; };
62	/* Móc cho công trình có hành vi riêng ở từng điểm dừng (Hầm sông Hàn: mặt cắt, mô phỏng dìm) và khi thoát Tour */
63	/* bridge: Tour 4 cầu tới cầu khác thì đổi bảng Thông số / danh sách góc nhìn (setupUI gắn selectBridge, tránh vòng import panel → camera → tour) */
64	/* sw: Tour Vòng quay Mặt Trời — gọi mỗi khi đổi điểm dừng (null = điểm thường) và khi thoát Tour (exit = true), sau khi cam.mode đã về 'orbit' */
65	export const tourHooks: { stop: ((s: TourStop) => void) | null; exit: (() => void) | null; bridge: ((k: BridgeKey) => void) | null; sw: ((phase: TourStop['sw'] | null, exit: boolean) => void) | null } = { stop: null, exit: null, bridge: null, sw: null };
66	
67	/* Giọng bật/tắt hoặc đổi ngôn ngữ: tính lại thời lượng (giữ nguyên vị trí trên đường bay) rồi đọc lại điểm dừng hiện tại */
68	function syncNarration() {
69	  const { i, f } = locate(activeTour, tour.t);
70	  for (const T of Object.values(TOURS)) fitDurations(T);
71	  tour.t = activeTour.durs.slice(0, i).reduce((a, b) => a + b, 0) + f * activeTour.durs[i];
72	  if (cam.mode === 'tour' && tour.shown >= 0) narration.play(activeTour.key, tour.shown); else narration.stop();
73	}
74	narration.onChange(syncNarration);
75	onChange(syncNarration);
