import { clamp, smooth } from '../../common/math';
import type { SongHanConfig } from '../../config';

/* [swingController] state machine quay cầu, phát event swingStart / swingOpen / swingClosed / stateChange */
export const SWING_STATES = ['CLOSED', 'STOP_TRAFFIC', 'UNLOCK', 'ROTATING_OPEN', 'OPEN', 'ROTATING_CLOSE', 'LOCK', 'REOPEN_TRAFFIC'] as const;
export type SwingState = typeof SWING_STATES[number];
export type Signal = 'green' | 'amber' | 'red';

/* Vận tốc góc hình thang: tăng dần – đều – giảm dần (a = phần thời gian tăng/giảm tốc) */
function trapezoidEase(u: number, a = 0.22) {
  u = clamp(u, 0, 1); const vmax = 1 / (1 - a);
  if (u < a) return vmax * u * u / (2 * a);
  if (u < 1 - a) return vmax * (u - a / 2);
  return 1 - vmax * (1 - u) * (1 - u) / (2 * a);
}
export class SwingController extends EventTarget {
  cfg: SongHanConfig;
  state: SwingState = 'CLOSED';
  t = 0;
  speed = 30;                     // hệ số tăng tốc so với thời gian thật
  angle = 0; lift = 0; pin = 1; barrier = 0;
  signal: Signal = 'green';
  closeAsked = false;
  fromTour = false;               // quay do Tour kích hoạt: đóng ngay khi tàu buồm qua hết luồng
  spanClear: () => boolean = () => true;
  canClose: () => boolean = () => true;
  canStart: () => boolean = () => true;     // thời tiết (bão) gán predicate; false → start() từ chối và phát 'swingBlocked'

  constructor(cfg: SongHanConfig) {
    super();
    this.cfg = cfg;
  }
  get busy() { return this.state !== 'CLOSED'; }
  get allowEntry() { return this.state === 'CLOSED' || (this.state === 'REOPEN_TRAFFIC' && this.signal === 'green'); }
  start(speed?: number) {
    if (this.state !== 'CLOSED') return false;
    if (!this.canStart()) { this.dispatchEvent(new Event('swingBlocked')); return false; }
    if (speed) this.speed = speed;
    this.go('STOP_TRAFFIC'); this.dispatchEvent(new Event('swingStart'));
    return true;
  }
  requestClose() { if (this.state === 'OPEN') this.closeAsked = true; }
  go(s: SwingState) {
    this.state = s; this.t = 0;
    if (s === 'OPEN') this.closeAsked = false;
    this.dispatchEvent(new CustomEvent<SwingState>('stateChange', { detail: s }));
    if (s === 'OPEN') this.dispatchEvent(new Event('swingOpen'));
    if (s === 'CLOSED') this.dispatchEvent(new Event('swingClosed'));
  }
  update(dt: number) {
    if (this.state === 'CLOSED') return;
    const T = this.cfg.timing, rot = Math.PI / 2 * this.cfg.rotateDir;
    this.t += dt * this.speed;
    const k = (d: number) => clamp(this.t / d, 0, 1);
    switch (this.state) {
      case 'STOP_TRAFFIC':
        this.signal = this.t < T.amber ? 'amber' : 'red';
        this.barrier = smooth(clamp((this.t - T.amber) / T.barrier, 0, 1));
        if (this.t > T.amber + T.barrier && (this.spanClear() || this.t > T.stopMax)) this.go('UNLOCK');
        break;
      case 'UNLOCK': {            // rút chốt rồi nâng nhẹ nhịp khỏi gối đầu cánh
        const u = k(T.unlock);
        this.pin = 1 - smooth(clamp(u * 2, 0, 1)); this.lift = smooth(clamp(u * 2 - 1, 0, 1)) * this.cfg.lift;
        if (u >= 1) this.go('ROTATING_OPEN');
        break;
      }
      case 'ROTATING_OPEN':
        this.angle = trapezoidEase(k(T.rotate)) * rot;
        if (k(T.rotate) >= 1) this.go('OPEN');
        break;
      case 'OPEN':
        if ((this.t > T.openHold || this.closeAsked) && this.canClose()) this.go('ROTATING_CLOSE');
        break;
      case 'ROTATING_CLOSE':
        this.angle = (1 - trapezoidEase(k(T.rotate))) * rot;
        if (k(T.rotate) >= 1) { this.angle = 0; this.go('LOCK'); }
        break;
      case 'LOCK': {              // hạ nhịp xuống gối rồi đẩy chốt khóa
        const u = k(T.lock);
        this.lift = (1 - smooth(clamp(u * 2, 0, 1))) * this.cfg.lift; this.pin = smooth(clamp(u * 2 - 1, 0, 1));
        if (u >= 1) this.go('REOPEN_TRAFFIC');
        break;
      }
      case 'REOPEN_TRAFFIC':
        this.barrier = 1 - smooth(k(T.barrier));
        this.signal = this.t >= T.barrier ? 'green' : 'red';
        if (this.t > T.barrier + 2) { this.barrier = 0; this.signal = 'green'; this.go('CLOSED'); }
        break;
    }
  }
}
---I18N
/* =====================================================================
   ĐA NGÔN NGỮ — bảng dịch giao diện, mặc định Tiếng Việt.
   Mỗi ngôn ngữ một file JSON trong locales/. Thêm ngôn ngữ: tạo file mới rồi khai báo trong LOCALES bên dưới.
   Chọn ngôn ngữ qua menu, hoặc link có #en, #ko, #ja, #zh, #th, #ar, #hi, #ru.
   ===================================================================== */
import vi from './locales/vi.json';
import en from './locales/en.json';
import ko from './locales/ko.json';
import ja from './locales/ja.json';
import zh from './locales/zh.json';
import th from './locales/th.json';
import ar from './locales/ar.json';
import hi from './locales/hi.json';
import ru from './locales/ru.json';

export type Locale = Record<string, unknown> & { _name: string; _dir?: 'rtl' | 'ltr' };
export type Stop = [title: string, text: string];

/* Thứ tự ở đây là thứ tự trong menu chọn ngôn ngữ */
const LOCALES: Record<string, Locale> = { vi, en, ko, ja, zh, th, ar, hi, ru } as Record<string, Locale>;

/* Font theo chữ viết — chỉ tải khi chọn ngôn ngữ đó */
const FONTS: Record<string, string> = {
  ko: 'Noto+Serif+KR:wght@600&family=Noto+Sans+KR:wght@400;500;600',
  ja: 'Noto+Serif+JP:wght@600&family=Noto+Sans+JP:wght@400;500;600',
  zh: 'Noto+Serif+SC:wght@600&family=Noto+Sans+SC:wght@400;500;600',
  th: 'Noto+Serif+Thai:wght@600&family=Noto+Sans+Thai:wght@400;500;600',
  ar: 'Noto+Naskh+Arabic:wght@600&family=Noto+Sans+Arabic:wght@400;500;600',
  hi: 'Noto+Serif+Devanagari:wght@600&family=Noto+Sans+Devanagari:wght@400;500;600',
  ru: 'Noto+Serif:wght@600&family=Noto+Sans:wght@400;500;600'
};
const STORE_KEY = 'cauRong.lang';
const listeners: ((code: string) => void)[] = [];
let lang = 'vi';

/* Chuỗi đã dịch; {tham_số} được thay bằng params. Khóa thiếu thì lấy Tiếng Việt, rồi chính khóa */
export function t(key: string, params?: Record<string, string | number> | null): string {
  let s = (LOCALES[lang] && LOCALES[lang][key]) ?? LOCALES.vi[key] ?? key;
  if (params && typeof s === 'string') s = s.replace(/\{(\w+)\}/g, (_, k) => String(params[k] ?? ''));
  return s as string;
}
/* Danh sách điểm dừng Tour (mảng [tiêu đề, lời giới thiệu]) */
export function stops(key: string): Stop[] {
  return ((LOCALES[lang] && LOCALES[lang][key]) ?? LOCALES.vi[key]) as Stop[];
}
export const getLang = () => lang;
export const onChange = (fn: (code: string) => void) => { listeners.push(fn); };

function loadFont(code: string) {
  if (!FONTS[code] || document.getElementById('font-' + code)) return;
  const l = document.createElement('link');
  l.id = 'font-' + code; l.rel = 'stylesheet';
  l.href = 'https://fonts.googleapis.com/css2?family=' + FONTS[code] + '&display=swap';
  document.head.appendChild(l);
}
export function apply(code: string) {
  if (!LOCALES[code]) code = 'vi';
  lang = code;
  const root = document.documentElement;
  root.lang = code; root.dir = LOCALES[code]._dir || 'ltr';
  loadFont(code);
  document.title = t('title');
  document.querySelectorAll<HTMLElement>('[data-i18n]').forEach((el) => { const v = t(el.dataset.i18n); if (v !== el.dataset.i18n) el.textContent = v; });   // khóa thiếu ở mọi ngôn ngữ (t() trả lại chính khóa): bỏ qua, phần tử giữ chữ đang có (của ngôn ngữ trước, chưa chắc là chữ mặc định trong HTML)
  document.querySelectorAll<HTMLElement>('[data-i18n-aria]').forEach((el) => { el.setAttribute('aria-label', t(el.dataset.i18nAria)); });
  const sel = document.getElementById('langSelect') as HTMLSelectElement;
  if (sel && sel.value !== code) sel.value = code;
  try { localStorage.setItem(STORE_KEY, code); } catch { /* bộ nhớ trình duyệt bị chặn */ }
  listeners.forEach((fn) => fn(code));
}

/* Dựng menu chọn ngôn ngữ và áp ngôn ngữ ban đầu: #mã trên link → lựa chọn đã lưu → Tiếng Việt */
export function initI18n() {
  const sel = document.getElementById('langSelect') as HTMLSelectElement;
  Object.entries(LOCALES).forEach(([code, d]) => {
    const o = document.createElement('option'); o.value = code; o.textContent = d._name; o.lang = code;
    sel.appendChild(o);
  });
  sel.addEventListener('change', () => apply(sel.value));
  let initial = 'vi';
  try { initial = localStorage.getItem(STORE_KEY) || 'vi'; } catch { /* bỏ qua */ }
  const hash = location.hash.replace('#', '');
  if (LOCALES[hash]) initial = hash;
  window.addEventListener('hashchange', () => { const h = location.hash.replace('#', ''); if (LOCALES[h]) apply(h); });
  apply(initial);
}
---LIVE
import { t, onChange as onLangChange } from '../i18n';
import { liveNightGate, type LiveEnv, type EnvMode } from '../realtime/liveEnv';
import type { EnvStore } from '../realtime/store';

/* ===== Giao diện hai chế độ Trực tiếp / Mô phỏng (D-043, spec §4.4) =====
   Chữ chế độ + chấm trong chỉ báo #envPill (#envMode), công tắc #envModeSw trong thẻ #envCard, dòng khóa #liveLock trong bảng Cài đặt, thông báo #liveNotice.
   Trực tiếp: thanh / nút Ngày–Đêm, ô chọn + thanh cường độ thời tiết, nút Kịch bản bão bị vô hiệu, và handler của chúng (setupUI.ts / weatherUI.ts) tự bỏ qua qua liveLocked().
   Tính năng cần ban đêm hỏi liveYieldForNight(dayNight.target) TRƯỚC khi ghi dayNight.target: Trực tiếp mà trời chưa tối thì chuyển sang Mô phỏng ('feature') và hiện #liveNotice;
   Trực tiếp mà trời đã tối thật thì ở lại Trực tiếp và không ghi (liveNightGate, realtime/liveEnv.ts).
   Không có bộ điều khiển (liveEnv null, dựng lỗi): không gọi bindLiveMode ⇒ mọi phần tử trên giữ `hidden`, không khóa gì, như trước D-043. */

let live: LiveEnv | null = null;
const LOCKED = ['timeSlider', 'btnNight', 'weatherSel', 'weatherK', 'btnWxStorm'];   // điều khiển mô phỏng thuần: vô hiệu ở Trực tiếp

/** Đang Trực tiếp: điều khiển mô phỏng không được ghi gì */
export const liveLocked = (): boolean => !!live && live.mode === 'live';
/** Tính năng cần ban đêm (trình diễn Cầu Rồng, góc rfHearts / swNight, tour Vòng quay): true = được ghi dayNight.target (đã ở / vừa chuyển sang Mô phỏng);
    false = đang Trực tiếp và trời đã tối thật, giữ Trực tiếp, không ghi. Gọi rồi mới đọc lại dayNight.target (chuyển Mô phỏng trả đêm mô phỏng đã nhớ) */
export function liveYieldForNight(target: number): boolean { return liveNightGate(live, target); }

export function bindLiveMode(le: LiveEnv, opts: { store: Pick<EnvStore, 'data' | 'onChange'>; syncSim: () => void; renderEnv: () => void }): void {
  live = le;
  const $ = (id: string) => document.getElementById(id);
  const env = $('env'), badge = $('envMode'), badgeTxt = badge?.querySelector<HTMLElement>('[data-mode-text]');
  const modes = $('envModes'), sw = $('envModeSw'), note = $('envModeNote');
  const btnL = $('envModeLive') as HTMLButtonElement | null, btnM = $('envModeManual') as HTMLButtonElement | null;
  const lock = $('liveLock'), lockTxt = lock?.querySelector<HTMLElement>('.live-lock-txt'), toManual = $('btnToManual'), toLive = $('btnToLive');
  const notice = $('liveNotice'), noticeLive = $('btnNoticeLive');
  for (const e of [badge, modes, lock]) if (e) e.hidden = false;
  const setText = (e: Element | null | undefined, s: string) => { if (e && e.textContent !== s) e.textContent = s; };
  /* Khám phá: Space / mũi tên là phím lái ⇒ bấm chuột xong thì bỏ focus khỏi #env / #liveLock (như blurInExplore của envUI.ts) */
  const blurInExplore = () => {
    const a = document.activeElement as HTMLElement | null;
    if (a && document.body.classList.contains('explore') && (env?.contains(a) || lock?.contains(a) || notice?.contains(a))) a.blur();
  };

  const render = () => {
    const m: EnvMode = le.mode, on = m === 'live';
    if (env && env.dataset.mode !== m) env.dataset.mode = m;
    setText(badgeTxt, t(on ? 'liveBadge' : 'simBadge'));
    for (const [b, bm] of [[btnL, 'live'], [btnM, 'manual']] as const) {
      if (!b) continue;
      b.setAttribute('aria-checked', String(m === bm));
      b.tabIndex = m === bm ? 0 : -1;   // nhóm radio: Tab vào nút đang chọn, mũi tên đổi
    }
    setText(note, t(on ? (opts.store.data ? 'liveNoteLive' : 'liveNoData') : 'liveNoteManual'));
    if (lock) { lock.dataset.mode = m; if (lockTxt) lockTxt.hidden = !on; }
    if (toManual) toManual.hidden = !on;
    if (toLive) toLive.hidden = on;
    for (const id of LOCKED) { const c = $(id) as HTMLButtonElement | HTMLInputElement | HTMLSelectElement | null; if (c && c.disabled !== on) c.disabled = on; }
    opts.renderEnv();   // nhãn đọc màn hình của chỉ báo kèm chế độ (envUI.ts đọc #env[data-mode])
  };

  /* Thông báo: tự ẩn sau 8 s; có nút "Về Trực tiếp" */
  let noticeTimer = 0;
  const hideNotice = () => { window.clearTimeout(noticeTimer); if (notice) notice.hidden = true; };
  const showNotice = () => { if (!notice) return; notice.hidden = false; window.clearTimeout(noticeTimer); noticeTimer = window.setTimeout(hideNotice, 8000); };

  const go = (m: EnvMode) => { if (le.mode !== m) le.setMode(m, 'user'); };
  le.onChange((why) => {
    if (why === 'data') { setText(note, t(le.mode === 'live' ? (opts.store.data ? 'liveNoteLive' : 'liveNoData') : 'liveNoteManual')); return; }
    render();
    if (le.mode === 'manual') opts.syncSim();   // về Mô phỏng: thanh / ô chọn hiện lại đúng trạng thái mô phỏng đã nhớ
    if (why === 'feature') showNotice(); else if (le.mode === 'live') hideNotice();
  });
  opts.store.onChange(() => { if (le.mode === 'live') setText(note, t(opts.store.data ? 'liveNoteLive' : 'liveNoData')); });
  onLangChange(render);

  btnL?.addEventListener('click', () => { go('live'); blurInExplore(); });
  btnM?.addEventListener('click', () => { go('manual'); blurInExplore(); });
  /* Bàn phím trong nhóm radio: mũi tên (cả hai chiều, chỉ hai lựa chọn nên RTL không đổi nghĩa) chọn + chuyển focus; Space / Enter chọn nút đang focus.
     stopPropagation: phím lái của khám phá (listener trên window) không nhận phím này; preventDefault: Space không cuộn trang */
  sw?.addEventListener('keydown', (e) => {
    const k = e.key;
    if (k === 'ArrowLeft' || k === 'ArrowRight' || k === 'ArrowUp' || k === 'ArrowDown') {
      const m: EnvMode = le.mode === 'live' ? 'manual' : 'live';
      go(m); (m === 'live' ? btnL : btnM)?.focus();
    } else if (k === ' ' || k === 'Enter') {
      const b = (e.target as HTMLElement | null)?.closest<HTMLElement>('[data-mode-btn]');
      if (b) go(b.dataset.modeBtn as EnvMode);
    } else return;
    e.preventDefault(); e.stopPropagation();
  });
  // Nút vừa bấm bị ẩn (đổi chỗ với nút kia): đưa focus sang nút kia để bàn phím không rơi về <body>
  const swap = (m: EnvMode, next: HTMLElement | null) => () => { go(m); if (document.body.classList.contains('explore')) blurInExplore(); else next?.focus({ preventScroll: true }); };
  toManual?.addEventListener('click', swap('manual', toLive));
  toLive?.addEventListener('click', swap('live', toManual));
  noticeLive?.addEventListener('click', () => { go('live'); hideNotice(); blurInExplore(); });
  render();
}
---COMPACT
import { CONFIG } from '../config';
import { onChange } from '../i18n';

/* ===== Chế độ gọn (điện thoại): body.compact + hai tờ Cài đặt / Góc nhìn (body.sheet-*) =====
   Máy tính dùng chung trạng thái tờ (bảng thu gọn thành nút ⚙ / ☰, D-025). Tờ thứ ba 'env': thẻ giờ + thời tiết thực tế (D-042, envUI.ts) */
export type Sheet = 'none' | 'settings' | 'views' | 'env';

export const ui: { compact: boolean; sheet: Sheet } = { compact: false, sheet: 'none' };

/* Mỗi lúc chỉ một tờ mở; 'none' = đóng hết. aria-expanded của hai nút mở tờ theo trạng thái */
export function openSheet(s: Sheet) {
  // Đóng một tờ khi focus còn bên trong: đưa focus về nút mở tờ đó, không để kẹt trên ô chọn đã ẩn (mũi tên sẽ đổi cài đặt thay vì lái dù)
  const SHEET: Record<Sheet, [string, string] | null> = { none: null, settings: ['.brand', 'btnSettings'], views: ['.views', 'btnViewsSheet'], env: ['#env', 'envPill'] };   // [khung tờ, nút mở]
  const prev = SHEET[ui.sheet], back = ui.sheet !== s && prev && document.activeElement?.closest(prev[0]) ? prev[1] : '';
  ui.sheet = s;
  document.body.classList.toggle('sheet-settings', s === 'settings');
  document.body.classList.toggle('sheet-views', s === 'views');
  document.body.classList.toggle('sheet-env', s === 'env');
  document.getElementById('btnSettings')?.setAttribute('aria-expanded', String(s === 'settings'));
  document.getElementById('btnViewsSheet')?.setAttribute('aria-expanded', String(s === 'views'));
  document.getElementById('envPill')?.setAttribute('aria-expanded', String(s === 'env'));
  if (back) document.getElementById(back)?.focus({ preventScroll: true });
}

export function closeSheets() { openSheet('none'); }

/* Đưa phần tử vào tầm nhìn: mở đúng tờ chứa nó (test và phím tắt dùng); phần tử ngoài hai tờ thì đóng hết.
   Điện thoại: chip .seg, nút Tour 4 cầu nằm trên thanh dưới (ngoài tờ); máy tính: cả .views là bảng thu gọn */
export function reveal(el: Element | null) {
  if (!el) return;
  if (el.closest('.brand')) openSheet('settings');
  else if (el.closest('#env')) openSheet('env');
  else if (el.closest('.view-list') || (!ui.compact && el.closest('.views'))) openSheet('views');
  else closeSheets();
}

/* Nút mở/đóng tờ; chạm khung 3D, chọn góc nhìn, Esc thì đóng; ghi --bar-h (cao thanh dưới) cho khung chú thích Tour / Kịch bản bão */
function wireSheets() {
  const toggle = (s: Sheet) => () => openSheet(ui.sheet === s ? 'none' : s);   // bấm lại thì đóng
  document.getElementById('btnSettings')?.addEventListener('click', toggle('settings'));
  document.getElementById('btnViewsSheet')?.addEventListener('click', toggle('views'));
  document.querySelectorAll('.sheet-close').forEach((b) => b.addEventListener('click', () => closeSheets()));
  // Bấm khung 3D khi có tờ mở: chỉ đóng tờ. Pha capture trên window chạy trước listener của canvas (exitTour, OrbitControls) nên chặn được cú bấm này
  window.addEventListener('pointerdown', (e) => {
    if (ui.sheet === 'none' || (e.target as Element | null)?.id !== 'scene') return;
    closeSheets(); e.stopPropagation(); e.preventDefault();
  }, true);
  document.querySelectorAll('[data-view]').forEach((b) => b.addEventListener('click', () => { if (ui.sheet !== 'none') closeSheets(); }));
  // Esc khi có tờ mở: chỉ đóng tờ, chặn các listener Esc khác (thoát Tour, xuống cabin, thoát bay); Esc lần sau mới tới chúng
  window.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape' || ui.sheet === 'none') return;
    closeSheets(); e.stopImmediatePropagation(); e.preventDefault();
  }, true);
  const bar = document.querySelector<HTMLElement>('.views');
  if (!bar || typeof ResizeObserver === 'undefined') return;
  // chỉ đo lúc thanh đóng: tờ Góc nhìn làm .views cao lên, tờ Cài đặt ẩn .views
  new ResizeObserver(() => { if (ui.compact && ui.sheet === 'none') document.documentElement.style.setProperty('--bar-h', bar.offsetHeight + 'px'); }).observe(bar);
}

/* Vệt mờ trên hàng chip .seg: .more-start / .more-end khi còn nội dung bị cuộn khuất ở đầu / cuối dòng (RTL: scrollLeft ≤ 0, đầu dòng ở bên phải) */
function wireSegFade() {
  const seg = document.querySelector<HTMLElement>('.seg');
  if (!seg) return;
  const update = () => {
    const max = seg.scrollWidth - seg.clientWidth;
    const pos = Math.abs(seg.scrollLeft);   // quãng đã cuộn từ đầu dòng, đúng cả LTR lẫn RTL
    seg.classList.toggle('more-start', ui.compact && pos > 8);
    seg.classList.toggle('more-end', ui.compact && max - pos > 8);
  };
  seg.addEventListener('scroll', update, { passive: true });
  window.addEventListener('resize', update);
  segFadeUpdate = update;
  if (typeof ResizeObserver !== 'undefined') new ResizeObserver(update).observe(seg);
  onChange(update);   // đổi ngôn ngữ đổi bề rộng chip nhưng không đổi hộp .seg nên ResizeObserver không báo
}
let segFadeUpdate = () => {};

/* Tour / kịch bản bão bật lên thì đóng tờ đang mở (class của body đổi) */
function wireAutoClose() {
  let was = false;
  new MutationObserver(() => {
    const on = document.body.classList.contains('touring') || document.body.classList.contains('wxrun');
    if (on && !was && ui.sheet !== 'none') closeSheets();
    was = on;
  }).observe(document.body, { attributes: true, attributeFilter: ['class'] });
}

export function setupCompactUI() {
  wireSheets();
  wireSegFade();
  wireAutoClose();
  const mq = window.matchMedia(CONFIG.ui.compactQuery);
  const apply = () => {
    const was = ui.compact;
    ui.compact = mq.matches;
    document.body.classList.toggle('compact', ui.compact);
    if (was !== ui.compact) closeSheets();   // qua ngưỡng gọn ↔ máy tính (cả hai chiều): không để tờ mở dở
    segFadeUpdate();
  };
  mq.addEventListener('change', apply);
  apply();
}

